/// positive, which cannot arise from `Self::to_continued_fraction`.
///
/// Rust: `exact::rational::Rational::from_continued_fraction`
#[pyfunction]
#[pyo3(name = "from_continued_fraction", signature = (cf))]
pub fn pyfn_rational_from_continued_fraction<'py>(py: Python<'py>, cf: Vec<crate::runtime::coerce::BigIntArg>) -> PyResult<pyo3::Bound<'py, pyo3::PyAny>> {
    let cf = cf.into_iter().map(|__e| __e.0).collect::<Vec<_>>();
    let __r = crate::runtime::guard(|| rust_physics_engine::exact::rational::Rational::from_continued_fraction(&cf));
    let __v = __r.map_err(crate::runtime::errors::InvalidArgumentError::new_err)?;
    let __v = __v.map_err(crate::runtime::map_geom)?;
    Ok(crate::runtime::coerce::rational_out(py, &__v)?)
}

/// The mediant `(a.num + b.num) / (a.den + b.den)`.
///
/// The mediant of two fractions always lies strictly between them, the
/// property the Stern-Brocot tree and Farey sequences are built on.
///
/// Rust: `exact::rational::Rational::mediant`
#[pyfunction]
#[pyo3(name = "mediant", signature = (a, b))]
pub fn pyfn_rational_mediant<'py>(py: Python<'py>, a: crate::runtime::coerce::RationalArg, b: crate::runtime::coerce::RationalArg) -> PyResult<pyo3::Bound<'py, pyo3::PyAny>> {
    let a = a.0;
    let b = b.0;
    let __r = crate::runtime::guard(|| rust_physics_engine::exact::rational::Rational::mediant(&a, &b));
    let __v = __r.map_err(crate::runtime::errors::InvalidArgumentError::new_err)?;
    Ok(crate::runtime::coerce::rational_out(py, &__v)?)
}

